def orbit(r,c,n=30):
    seen={(r,c)}
    changed=True
    while changed:
        changed=False
        for x,y in list(seen):
            cand={(y,x)}
            if 2<=x<=29: cand.add((31-x,y))
            if 2<=y<=29: cand.add((x,31-y))
            if 2<=x<=29 and 2<=y<=29: cand.add((31-x,31-y))
            for z in cand:
                if 0<=z[0]<n and 0<=z[1]<n and z not in seen:
                    seen.add(z);changed=True
    return seen

